// The other package: the same two names, a different meaning for each. Its
// `helper` subtracts where `pkg_a`'s adds, so a program that got the two
// confused would not merely link — it would print a different number.

const helper = (n: i32): i32 => n - 1;

export const scale = (n: i32): i32 => helper(n) * 3;
